WRITE_OWNER=r'''
DECLARE R mta.fresh_mta_calculationrun; A mta.fresh_mta_runscopeattempt;
 allowed boolean; request_node jsonb; requested_scope text; compatibility text; capture_status text;
BEGIN
 IF to_regclass('fresh_control.owned_namespace') IS NULL THEN RETURN false; END IF;
 EXECUTE 'SELECT count(*)=1 FROM fresh_control.owned_namespace reg '
  ||'WHERE reg.singleton AND reg.database_oid=(SELECT oid FROM pg_database WHERE datname=current_database()) '
  ||'AND reg.database_name=current_database() AND reg.owner_oid=(SELECT oid FROM pg_roles WHERE rolname=current_user) '
  ||'AND reg.issuer_oid=(SELECT oid FROM pg_roles WHERE rolname=session_user)' INTO allowed;
 IF NOT coalesce(allowed,false) THEN RETURN false; END IF;
 SELECT * INTO R FROM mta.fresh_mta_calculationrun WHERE id=target;
 IF R.id IS NULL OR R.kind<>'DAILY_CHAIN' OR R.status<>'RUNNING' OR R.evidence_mode<>'production' THEN RETURN false; END IF;
 SELECT value->1 INTO request_node FROM jsonb_array_elements(R.input_payload#>'{tree,object}') WHERE value->>0='scope_request';
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(request_node->'object') N WHERE
   N.value->>0='schema' AND N.value->1->>'scalar'='fresh-native-report-placement-request-v1') THEN RETURN false; END IF;
 SELECT value->1->>'scalar' INTO requested_scope FROM jsonb_array_elements(request_node->'object') WHERE value->>0='scope';
 SELECT value->1->>'scalar' INTO compatibility FROM jsonb_array_elements(request_node->'object') WHERE value->>0='compatibility_digest';
 SELECT status INTO capture_status FROM mta.fresh_mta_mdmdailyinputcapture WHERE run_id=R.id;
 IF requested_scope='Full' THEN
  RETURN capture_status='CONSUMED' AND current_setting('fresh.mdm_consuming_run',true)=R.id::text
   AND NOT EXISTS(SELECT 1 FROM mta.fresh_mta_runscopeattempt WHERE run_id=R.id);
 END IF;
 IF requested_scope NOT IN ('UptoBPR','UptoDBM') THEN RETURN false; END IF;
 SELECT * INTO A FROM mta.fresh_mta_runscopeattempt WHERE run_id=R.id AND status='ACTIVE';
 IF A.id IS NULL OR A.worker_token::text IS DISTINCT FROM current_setting('fresh.scope_worker',true)
  OR A.compatibility_digest IS DISTINCT FROM compatibility OR A.input_digest IS DISTINCT FROM R.input_digest
  OR A.input_manifest_digest IS DISTINCT FROM R.input_manifest_digest
  OR A.action_revision IS DISTINCT FROM mta.scope_action_revision(R.id) THEN RETURN false; END IF;
 RETURN capture_status='CAPTURED' OR (capture_status='CONSUMED' AND mta.pending_day_final(R.id));
END
'''

PLACEMENT_SOURCE=r'''
 SELECT coalesce(
  R.kind='DAILY_CHAIN' AND R.status IN ('RUNNING','SUCCEEDED') AND R.evidence_mode='production'
  AND P.operational_attempt_id IS NULL AND P.input_digest=R.input_digest
  AND P.input_manifest_digest=R.input_manifest_digest
  AND P.source_digest ~ '^[0-9a-f]{64}$' AND P.profile_digest ~ '^[0-9a-f]{64}$'
  AND P.scope_request_digest ~ '^[0-9a-f]{64}$' AND P.configuration_digest ~ '^[0-9a-f]{64}$'
  AND P.recipe_digest ~ '^[0-9a-f]{64}$' AND P.action_digest ~ '^[0-9a-f]{64}$'
  AND P.candidate_digest ~ '^[0-9a-f]{64}$' AND P.catalogue_digest ~ '^[0-9a-f]{64}$'
  AND P.digest ~ '^[0-9a-f]{64}$'
  AND jsonb_typeof(P.metadata)='object' AND octet_length(P.metadata::text)<=2097152
  AND P.metadata->>'schema'='fresh-runtime-report-placement-publication-v1'
  AND P.metadata#>>'{candidate,candidate_id}'=P.id::text
  AND P.metadata#>>'{candidate,placement}'=P.placement
  AND P.metadata#>>'{candidate,configuration_digest}'=P.configuration_digest
  AND P.metadata#>>'{candidate,digest}'=P.candidate_digest
  AND jsonb_typeof(P.metadata->'catalogue')='object'
  AND P.metadata#>'{authority,request_node}'=(SELECT value->1 FROM jsonb_array_elements(R.input_payload#>'{tree,object}') WHERE value->>0='scope_request')
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(P.metadata#>'{authority,request_node,object}') N
      WHERE N.value->>0='schema' AND N.value->1->>'scalar'='fresh-native-report-placement-request-v1')
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(P.metadata#>'{authority,request_node,object}') N
      WHERE N.value->>0='publication_recipe' AND N.value->1->>'scalar'=P.recipe_digest)
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(P.metadata#>'{authority,request_node,object}') N,
      LATERAL jsonb_array_elements(CASE WHEN N.value->>0='runtime_reports' THEN N.value->1->'object' ELSE '[]'::jsonb END) V
      WHERE V.value->>0='configuration_digest' AND V.value->1->>'scalar'=P.configuration_digest)
  AND P.metadata#>>'{authority,owner,schema}'='fresh-runtime-report-placement-publication-v1'
  AND P.metadata#>>'{authority,owner,run_id}'=R.id::text
  AND P.metadata#>>'{authority,owner,placement}'=P.placement
  AND P.metadata#>>'{authority,owner,kind}'=P.owner_kind
  AND P.metadata#>>'{authority,owner,input_digest}'=P.input_digest
  AND P.metadata#>>'{authority,owner,input_manifest_digest}'=P.input_manifest_digest
  AND P.metadata#>>'{authority,owner,profile_digest}'=P.profile_digest
  AND P.metadata#>>'{authority,owner,request_digest}'=P.scope_request_digest
  AND P.metadata#>>'{authority,owner,action_revision}'=P.action_revision::text
  AND jsonb_typeof(P.metadata#>'{authority,owner,cut}')='object'
  AND P.metadata#>'{authority,owner,cut}'<>'{}'::jsonb
  AND P.metadata#>>'{authority,images,schema}'='fresh-runtime-report-stage-images-v1'
  AND P.metadata#>>'{authority,images,candidate_id}'=P.id::text
  AND P.metadata#>>'{authority,images,placement}'=P.placement
  AND jsonb_typeof(P.metadata#>'{authority,images,images}')='object'
  AND ((P.placement='PostImporter' AND P.catalogue_parent_id IS NULL
      AND P.metadata->'previous_digest'='null'::jsonb AND jsonb_typeof(P.metadata->'anchor')='object')
   OR (V.run_id=R.id AND V.placement=CASE P.placement WHEN 'PostBPR' THEN 'PostImporter'
       WHEN 'PostDBM' THEN 'PostBPR' WHEN 'PostBTR' THEN 'PostDBM' WHEN 'Final' THEN 'PostBTR' END
      AND V.metadata->>'schema'=P.metadata->>'schema' AND V.recipe_digest=P.recipe_digest
      AND V.configuration_digest=P.configuration_digest AND V.scope_request_digest=P.scope_request_digest
      AND P.metadata->>'previous_digest'=V.digest AND P.metadata->'anchor'='null'::jsonb))
  AND ((P.owner_kind='FULL_COMPLETION' AND P.phase_id IS NULL AND P.scope_attempt_id IS NULL
      AND P.action_revision=0 AND P.metadata#>'{authority,owner,phase_id}'='null'::jsonb
      AND P.metadata#>'{authority,owner,phase_digest}'='null'::jsonb
      AND C.status='CONSUMED' AND NOT EXISTS(SELECT 1 FROM mta.fresh_mta_runscopeattempt WHERE run_id=R.id)
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(P.metadata#>'{authority,request_node,object}') N
          WHERE N.value->>0='scope' AND N.value->1->>'scalar'='Full'))
   OR (P.owner_kind IN ('SCOPED_PHASE','SCOPED_FINAL') AND A.run_id=R.id
      AND A.input_digest=R.input_digest AND A.input_manifest_digest=R.input_manifest_digest
      AND A.action_revision=P.action_revision AND S.run_id=R.id AND S.input_digest=R.input_digest
      AND S.source_id=C.source_id AND S.capture_digest=C.revision_digest
      AND Q.run_id=R.id AND Q.state_sealed AND Q.input_digest=R.input_digest
      AND Q.digest=P.metadata#>>'{authority,owner,phase_digest}'
      AND Q.id::text=P.metadata#>>'{authority,owner,phase_id}'
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(P.metadata#>'{authority,request_node,object}') N
          WHERE N.value->>0='scope' AND N.value->1->>'scalar' IN ('UptoBPR','UptoDBM'))
      AND ((P.owner_kind='SCOPED_PHASE' AND S.id=Q.id AND S.state_sealed
          AND S.phase=CASE P.placement WHEN 'PostImporter' THEN 'PRE_BPR' WHEN 'PostBPR' THEN 'BPR' WHEN 'PostDBM' THEN 'DBM' END)
       OR (P.owner_kind='SCOPED_FINAL' AND P.placement IN ('PostBTR','Final') AND S.phase='DAY_FINAL'
          AND S.attempt_id=A.id AND Q.phase='DBM' AND C.status='CONSUMED'
          AND ((S.state_sealed AND R.status='SUCCEEDED' AND S.metadata->>'parent_acceptance_digest'=Q.digest)
              OR (NOT S.state_sealed AND R.status='RUNNING' AND mta.pending_day_final(R.id))))))),false)
 FROM mta.fresh_mta_calculationrun R
 LEFT JOIN mta.fresh_mta_mdmdailyinputcapture C ON C.run_id=R.id
 LEFT JOIN mta.fresh_mta_runphaseacceptance S ON S.id=P.phase_id
 LEFT JOIN mta.fresh_mta_runphaseacceptance Q ON Q.id::text=P.metadata#>>'{authority,owner,phase_id}'
 LEFT JOIN mta.fresh_mta_runscopeattempt A ON A.id=P.scope_attempt_id
 LEFT JOIN mta.fresh_mta_runtimereportpublication V ON V.id=P.catalogue_parent_id
 WHERE R.id=P.run_id
'''
SOURCE=" SELECT CASE WHEN P.metadata->>'schema'='fresh-runtime-report-placement-publication-v1' THEN ("+PLACEMENT_SOURCE+") ELSE ("+prior.SOURCE+") END "

BRANCH=r'''
 IF TG_OP='INSERT' AND NEW.metadata->>'schema'='fresh-runtime-report-placement-publication-v1' THEN
  SELECT * INTO run_row FROM mta.fresh_mta_calculationrun WHERE id=NEW.run_id FOR UPDATE;
  IF NOT coalesce(mta.runtime_report_write_owner(NEW.run_id),false)
    OR NOT coalesce(mta.runtime_report_publication_source(NEW),false)
    OR current_setting('fresh.runtime_report_candidate',true) IS DISTINCT FROM NEW.id::text THEN
   RAISE EXCEPTION 'Placement publication requires its authenticated owner/source'; END IF;
  IF NEW.owner_kind<>'FULL_COMPLETION' THEN
   SELECT * INTO attempt_row FROM mta.fresh_mta_runscopeattempt WHERE id=NEW.scope_attempt_id FOR UPDATE;
   IF attempt_row.status<>'ACTIVE' OR attempt_row.worker_token::text IS DISTINCT FROM current_setting('fresh.scope_worker',true)
     OR NEW.action_revision IS DISTINCT FROM mta.scope_action_revision(NEW.run_id) THEN
    RAISE EXCEPTION 'Stale placement publication worker/action cut'; END IF;
   IF NEW.owner_kind='SCOPED_FINAL' THEN
    IF NEW.phase_id::text IS DISTINCT FROM current_setting('fresh.scope_phase',true)
      OR NOT mta.pending_day_final(NEW.run_id) THEN RAISE EXCEPTION 'Exact pending final placement owner required'; END IF;
   ELSIF NOT EXISTS(SELECT 1 FROM mta.scope_head(NEW.run_id) H JOIN mta.fresh_mta_runphaseacceptance S
       ON S.id=NEW.phase_id AND S.phase=H.phase AND S.digest=H.digest) THEN
    RAISE EXCEPTION 'Placement phase head changed';
   END IF;
  END IF;
  RETURN NEW;
 END IF;
'''
assert prior.GUARD.count('BEGIN\n')==1
GUARD=prior.GUARD.replace('BEGIN\n','BEGIN\n'+BRANCH,1)

IMAGE_GUARD=r'''
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Report stage source images are immutable'; END IF;
 IF NEW.vf_ordinal<0 OR split_part(NEW.vf_image,'/',1)<>'runtime-report'
  OR split_part(NEW.vf_image,'/',2) IS DISTINCT FROM current_setting('fresh.runtime_report_candidate',true)
  OR NEW.vf_image IS DISTINCT FROM 'runtime-report/'||split_part(NEW.vf_image,'/',2)||'/'||TG_ARGV[0]
  OR EXISTS(SELECT 1 FROM mta.fresh_mta_runtimereportpublication WHERE id::text=split_part(NEW.vf_image,'/',2)) THEN
  RAISE EXCEPTION 'Report image is outside its unregistered candidate'; END IF;
 RETURN NEW;
END
'''
IMAGE_BATCH=r'''
BEGIN
 IF EXISTS(SELECT 1 FROM (SELECT DISTINCT vf_run_id FROM new_rows) N
   WHERE NOT coalesce(mta.runtime_report_write_owner(N.vf_run_id),false)) THEN
  RAISE EXCEPTION 'Report image batch requires its native publication owner'; END IF;
 RETURN NULL;
END
'''
IMAGE_COMMIT=r'''
DECLARE P mta.fresh_mta_runtimereportpublication; item jsonb;
BEGIN
 SELECT * INTO P FROM mta.fresh_mta_runtimereportpublication WHERE id::text=split_part(NEW.vf_image,'/',2);
 item:=P.metadata#>ARRAY['authority','images','images',TG_ARGV[0]];
 IF P.id IS NULL OR P.run_id IS DISTINCT FROM NEW.vf_run_id OR item IS NULL
  OR item->>'image' IS DISTINCT FROM NEW.vf_image OR item->>'table' IS DISTINCT FROM 'placement/'||TG_ARGV[0]
  OR NOT coalesce(mta.runtime_report_publication_source(P),false) THEN
  RAISE EXCEPTION 'Report image has no matching committed publication'; END IF;
 RETURN NULL;
END
'''
RECEIPT_COMMIT=r'''
DECLARE P mta.fresh_mta_runtimereportpublication; R mta.fresh_mta_calculationrun;
 logical text; item jsonb; physical text; actual bigint; lo bigint; hi bigint;
BEGIN
 IF NEW.metadata->>'schema'<>'fresh-runtime-report-placement-publication-v1' THEN RETURN NULL; END IF;
 SELECT * INTO P FROM mta.fresh_mta_runtimereportpublication WHERE id=NEW.id;
 SELECT * INTO R FROM mta.fresh_mta_calculationrun WHERE id=P.run_id;
 IF NOT coalesce(mta.runtime_report_publication_source(P),false) THEN RAISE EXCEPTION 'Placement source lost at commit'; END IF;
 IF P.owner_kind IN ('FULL_COMPLETION','SCOPED_FINAL') THEN
  IF R.status<>'SUCCEEDED' OR (SELECT count(*) FROM mta.fresh_mta_runtimereportpublication V
      WHERE V.run_id=P.run_id AND V.metadata->>'schema'=P.metadata->>'schema'
       AND V.configuration_digest=P.configuration_digest AND V.recipe_digest=P.recipe_digest)<>5 THEN
   RAISE EXCEPTION 'Terminal placement requires the complete atomic publication'; END IF;
 END IF;
 FOR logical,item IN SELECT * FROM jsonb_each(P.metadata#>'{authority,images,images}') LOOP
  physical:=mta.runtime_report_image_table(logical);
  IF physical IS NULL OR item->>'image' IS DISTINCT FROM 'runtime-report/'||P.id::text||'/'||logical
    OR item->>'table' IS DISTINCT FROM 'placement/'||logical
    OR jsonb_typeof(item->'count') IS DISTINCT FROM 'number' OR (item->>'count')!~'^[0-9]+$' THEN
   RAISE EXCEPTION 'Placement image declaration differs'; END IF;
  EXECUTE format('SELECT count(*),min(vf_ordinal),max(vf_ordinal) FROM mta_state.%I WHERE vf_run_id=$1 AND vf_image=$2',physical)
   INTO actual,lo,hi USING P.run_id,item->>'image';
  IF actual<>(item->>'count')::bigint OR (actual>0 AND (lo<>0 OR hi<>actual-1)) THEN
   RAISE EXCEPTION 'Placement image count/ordinal differs'; END IF;
 END LOOP;
 RETURN NULL;
END
'''


def quote(value):return '"'+value.replace('"','""')+'"'
def literal(value):return "'"+value.replace("'","''")+"'"


def function(name,arguments,returns,language,body,*,replace=False,stable=False):
    return ('CREATE '+('OR REPLACE ' if replace else '')+'FUNCTION mta.'+name+'('+arguments+') RETURNS '+returns+
        ' LANGUAGE '+language+(' STABLE' if stable else '')+' SET search_path=pg_catalog,mta AS $body$'+body+'$body$;\n'+
        'REVOKE ALL ON FUNCTION mta.'+name+'('+arguments+') FROM PUBLIC;\n')


def exact(name,body):
    return ("DO $pre$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure("+literal(name)+") "+
        "AND prosrc=$expected$"+body+"$expected$ AND NOT prosecdef "+
        "AND proconfig=ARRAY['search_path=pg_catalog, mta']::text[]) THEN "+
        "RAISE EXCEPTION 'Exact previous runtime report guard required'; END IF; END $pre$;\n")


NAMES=tuple(name for name,_columns in TABLES.values())
ADDED="""
 IF TG_TABLE_SCHEMA='mta_state' AND TG_TABLE_NAME=ANY(ARRAY["""+','.join(map(literal,NAMES))+"""]::text[]) AND TG_OP='INSERT' THEN
  IF NOT EXISTS(SELECT 1 FROM (SELECT DISTINCT vf_run_id FROM new_rows) N
    WHERE NOT coalesce(mta.runtime_report_write_owner(N.vf_run_id),false)) THEN RETURN NULL; END IF;
  RAISE EXCEPTION 'Unowned report-stage image insertion';
 END IF;
"""
assert OLD.count(" IF kind='immutable' THEN")==1
NEW=OLD.replace(" IF kind='immutable' THEN",ADDED+" IF kind='immutable' THEN",1)

SQL=exact('mta.runtime_report_publication_source(mta.fresh_mta_runtimereportpublication)',prior.SOURCE)
SQL+=exact('mta.guard_runtime_report_publication()',prior.GUARD)
SQL+=function('runtime_report_write_owner','target uuid','boolean','plpgsql',WRITE_OWNER,stable=True)
SQL+=function('runtime_report_publication_source','P mta.fresh_mta_runtimereportpublication','boolean','sql',SOURCE,replace=True,stable=True)
SQL+=function('guard_runtime_report_publication','','trigger','plpgsql',GUARD,replace=True)
TABLE_LOOKUP=' SELECT physical FROM (VALUES '+','.join('('+literal(logical)+','+literal(name)+')'
    for logical,(name,_columns) in TABLES.items())+') AS T(logical,physical) WHERE T.logical=source_name '
SQL+=function('runtime_report_image_table','source_name text','text','sql',TABLE_LOOKUP,stable=True)
for name,body in (('guard_runtime_report_image',IMAGE_GUARD),('guard_runtime_report_image_batch',IMAGE_BATCH),
                  ('check_runtime_report_image',IMAGE_COMMIT),('check_runtime_report_placement',RECEIPT_COMMIT)):
    SQL+=function(name,'','trigger','plpgsql',body)

REVERSE="""DO $pre$ BEGIN
 IF EXISTS(SELECT 1 FROM mta.fresh_mta_runtimereportpublication WHERE metadata->>'schema'='fresh-runtime-report-placement-publication-v1')
 THEN RAISE EXCEPTION 'Accepted placement reports require a compatible forward release'; END IF;
END $pre$;\n"""
PG_TYPES={'int':'bigint','bigint':'bigint','bit':'boolean','date':'date','datetime':'timestamp without time zone',
 'decimal':'numeric','numeric':'numeric','float':'double precision','real':'double precision',
 'nvarchar':'text','varchar':'text','nchar':'text','xml':'text'}
for logical,(name,columns) in TABLES.items():
    table='mta_state.'+quote(name)
    SQL+='CREATE TABLE '+table+' (vf_run_id uuid NOT NULL REFERENCES mta.fresh_mta_calculationrun(id) ON DELETE RESTRICT, '
    SQL+='vf_image text NOT NULL,vf_ordinal bigint NOT NULL CHECK (vf_ordinal>=0),'
    SQL+='vf_publication_id uuid GENERATED ALWAYS AS (split_part(vf_image,\'/\',2)::uuid) STORED '
    SQL+='REFERENCES mta.fresh_mta_runtimereportpublication(id) DEFERRABLE INITIALLY DEFERRED,'
    SQL+=','.join(quote(field)+' '+PG_TYPES[kind] for field,kind in columns)
    SQL+=',PRIMARY KEY(vf_run_id,vf_image,vf_ordinal));\n'
    SQL+='CREATE TRIGGER runtime_report_image_immutable BEFORE INSERT OR UPDATE OR DELETE ON '+table+" FOR EACH ROW EXECUTE FUNCTION mta.guard_runtime_report_image("+literal(logical)+");\n"
    SQL+='CREATE TRIGGER runtime_report_image_no_truncate BEFORE TRUNCATE ON '+table+" FOR EACH STATEMENT EXECUTE FUNCTION mta.guard_runtime_report_image("+literal(logical)+");\n"
    SQL+='CREATE TRIGGER runtime_report_image_batch AFTER INSERT ON '+table+' REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION mta.guard_runtime_report_image_batch();\n'
    SQL+='CREATE CONSTRAINT TRIGGER runtime_report_image_committed AFTER INSERT ON '+table+' DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION mta.check_runtime_report_image('+literal(logical)+');\n'
    for operation,reference in (('INSERT','NEW TABLE AS new_rows'),('UPDATE','OLD TABLE AS old_rows NEW TABLE AS new_rows'),('DELETE','OLD TABLE AS old_rows'),('TRUNCATE','')):
        SQL+='CREATE TRIGGER ingestion_watch_'+operation.lower()+' AFTER '+operation+' ON '+table+' '
        if reference:SQL+='REFERENCING '+reference+' '
        SQL+="FOR EACH STATEMENT EXECUTE FUNCTION mta.ingestion_watch('operational');\n"
    REVERSE+='DROP TABLE '+table+';\n'
SQL+='CREATE CONSTRAINT TRIGGER runtime_report_placement_committed AFTER INSERT ON mta.fresh_mta_runtimereportpublication DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION mta.check_runtime_report_placement();\n'
SQL+=transition(OLD,NEW)
REVERSE+='DROP TRIGGER runtime_report_placement_committed ON mta.fresh_mta_runtimereportpublication;\n'
REVERSE+=transition(NEW,OLD)
REVERSE+=function('runtime_report_publication_source','P mta.fresh_mta_runtimereportpublication','boolean','sql',prior.SOURCE,replace=True,stable=True)
REVERSE+=function('guard_runtime_report_publication','','trigger','plpgsql',prior.GUARD,replace=True)
for name,args in (('runtime_report_write_owner','uuid'),('runtime_report_image_table','text'),
    ('guard_runtime_report_image',''),('guard_runtime_report_image_batch',''),('check_runtime_report_image',''),('check_runtime_report_placement','')):
    REVERSE+='DROP FUNCTION mta.'+name+'('+args+');\n'


class Migration(migrations.Migration):

    dependencies = [
        ('fresh_mta', '0230_runtime_report_publication_guards'),
    ]

    operations = [migrations.RunSQL(SQL,REVERSE)]
